local PotpourriBowlMaker = {}
local PRODUCTS = {
    iron_potpourribowl = { name = "Železni skleda za potpuriji", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni skleda za potpuriji za glasbila." },
    bronze_potpourribowl = { name = "Bronast skleda za potpuriji", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast skleda za potpuriji za fino glasbo." },
    silver_potpourribowl = { name = "Srebrn skleda za potpuriji", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn skleda za potpuriji za plemiške glasbenike." },
    gilded_potpourribowl = { name = "Pozlačen skleda za potpuriji", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen skleda za potpuriji za dvorne glasbenike." },
    jewel_set_potpourribowl = { name = "Draguljast skleda za potpuriji", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast skleda za potpuriji za kraljevske glasbenike." },
    royal_sovereign_potpourribowl = { name = "Kraljevski suveren skleda za potpuriji", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren skleda za potpuriji z biseri za krono." },
}
local BUILDINGS = {
    potpourribowl_workshop = { name = "Potpourribowl delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    potpourribowl_house = { name = "Potpourribowl hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_potpourribowl_atelier = { name = "Mojstrski potpourribowl atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_potpourribowl_palace = { name = "Suverena potpourribowl palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
PotpourriBowlMaker.ironStock = 12; PotpourriBowlMaker.bronzeStock = 10; PotpourriBowlMaker.woodStock = 16; PotpourriBowlMaker.leatherStock = 10; PotpourriBowlMaker.silverStock = 8; PotpourriBowlMaker.goldStock = 6; PotpourriBowlMaker.jewelStock = 4; PotpourriBowlMaker.pearlStock = 4
PotpourriBowlMaker.productStock = {}; PotpourriBowlMaker.buildings = {}; PotpourriBowlMaker.maker = nil; PotpourriBowlMaker.activeMaking = {}; PotpourriBowlMaker.totalProducts = 0; PotpourriBowlMaker.dayTimer = 0
function PotpourriBowlMaker.init() PotpourriBowlMaker.ironStock=12; PotpourriBowlMaker.bronzeStock=10; PotpourriBowlMaker.woodStock=16; PotpourriBowlMaker.leatherStock=10; PotpourriBowlMaker.silverStock=8; PotpourriBowlMaker.goldStock=6; PotpourriBowlMaker.jewelStock=4; PotpourriBowlMaker.pearlStock=4; PotpourriBowlMaker.productStock={}; PotpourriBowlMaker.buildings={}; PotpourriBowlMaker.maker=nil; PotpourriBowlMaker.activeMaking={}; PotpourriBowlMaker.totalProducts=0; PotpourriBowlMaker.dayTimer=0; print("[PotpourriBowlMaker] Royal Potpourri Bowl Maker System initialized (6 products, 4 buildings)") end
function PotpourriBowlMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PotpourriBowlMaker.maker={name=n or ("Skledar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Skledar najet: %s (spretnost: %d)",PotpourriBowlMaker.maker.name,s),"success") end; return true end
function PotpourriBowlMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PotpourriBowlMaker.build(id) local ok,e=PotpourriBowlMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PotpourriBowlMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PotpourriBowlMaker.getQualityBonus() local b=0; for _,bd in ipairs(PotpourriBowlMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PotpourriBowlMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PotpourriBowlMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and PotpourriBowlMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and PotpourriBowlMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and PotpourriBowlMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PotpourriBowlMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PotpourriBowlMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PotpourriBowlMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PotpourriBowlMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PotpourriBowlMaker.buildings==0 then return false,"Potrebna skledna delavnica" end; if not PotpourriBowlMaker.maker then return false,"Potreben skledar" end; return true end
function PotpourriBowlMaker.make(pt,qty) qty=qty or 1; local ok,e=PotpourriBowlMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PotpourriBowlMaker.ironStock=PotpourriBowlMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then PotpourriBowlMaker.bronzeStock=PotpourriBowlMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then PotpourriBowlMaker.woodStock=PotpourriBowlMaker.woodStock-d.woodCost*qty end; if d.leatherCost then PotpourriBowlMaker.leatherStock=PotpourriBowlMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PotpourriBowlMaker.silverStock=PotpourriBowlMaker.silverStock-d.silverCost*qty end; if d.goldCost then PotpourriBowlMaker.goldStock=PotpourriBowlMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PotpourriBowlMaker.jewelStock=PotpourriBowlMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PotpourriBowlMaker.pearlStock=PotpourriBowlMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PotpourriBowlMaker.maker then t=math.max(1,t-math.floor(PotpourriBowlMaker.maker.skill/13)) end; table.insert(PotpourriBowlMaker.activeMaking,{id="potpourribowl_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PotpourriBowlMaker.completeMaking(m) local q=1.0+(PotpourriBowlMaker.getQualityBonus()/100); if PotpourriBowlMaker.maker then q=q+(PotpourriBowlMaker.maker.skill/140) end; q=math.min(2.5,q); PotpourriBowlMaker.productStock[m.productType]=(PotpourriBowlMaker.productStock[m.productType] or 0)+m.quantity; PotpourriBowlMaker.totalProducts=PotpourriBowlMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PotpourriBowlMaker.maker then PotpourriBowlMaker.maker.itemsMade=PotpourriBowlMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PotpourriBowlMaker.maker.skill=math.min(100,PotpourriBowlMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Skleda izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"potpourribowl.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PotpourriBowlMaker.update(dt) if not _G.state then return end; PotpourriBowlMaker.dayTimer=PotpourriBowlMaker.dayTimer+dt; if PotpourriBowlMaker.dayTimer>=30 then PotpourriBowlMaker.dayTimer=0; for i=#PotpourriBowlMaker.activeMaking,1,-1 do local m=PotpourriBowlMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PotpourriBowlMaker.completeMaking(m); table.remove(PotpourriBowlMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PotpourriBowlMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PotpourriBowlMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PotpourriBowlMaker.getStats() return {ironStock=PotpourriBowlMaker.ironStock,bronzeStock=PotpourriBowlMaker.bronzeStock,woodStock=PotpourriBowlMaker.woodStock,leatherStock=PotpourriBowlMaker.leatherStock,silverStock=PotpourriBowlMaker.silverStock,goldStock=PotpourriBowlMaker.goldStock,jewelStock=PotpourriBowlMaker.jewelStock,pearlStock=PotpourriBowlMaker.pearlStock,productStock=PotpourriBowlMaker.productStock,numBuildings=#PotpourriBowlMaker.buildings,hasMaker=PotpourriBowlMaker.maker~=nil,makerName=PotpourriBowlMaker.maker and PotpourriBowlMaker.maker.name or "—",makerSkill=PotpourriBowlMaker.maker and PotpourriBowlMaker.maker.skill or 0,activeMaking=#PotpourriBowlMaker.activeMaking,totalProducts=PotpourriBowlMaker.totalProducts} end
return PotpourriBowlMaker
